fn max(a: &Vec<i32>, n: usize) -> i32 {
    // Preconditions (by problem statement):
    // 1) n > 0
    // 2) n <= a.len()
    // 3) n < 1000
    debug_assert!(n > 0 && n <= a.len() && n < 1000);

    // Initialize the maximum to the first element
    let mut max_val = a[0];

    // Scan through the remaining n-1 elements
    for &x in &a[1..n] {
        if x > max_val {
            max_val = x;
        }
    }

    max_val
}

